import { get, handleApiError, post } from '@helpers/httpClient';

import { mapCommentBranchToFront, mapCommentToFront } from '../@mappers/comments.mapper';
import { IComment, ICommentBranch } from '../@types/comments.types';
import {
  ICommentAddDTO,
  ICommentBranchParamsDTO,
  ICommentDTO,
} from '../@types/DTO/comments.dto.types';

const clearNullAndUndefined = (
  params: Partial<ICommentBranchParamsDTO>,
): Partial<ICommentBranchParamsDTO> => {
  const newParams: Partial<ICommentBranchParamsDTO> = {};
  Object.keys(params).forEach((ke) => {
    const k = ke as keyof ICommentBranchParamsDTO;
    if (params[k]) {
      newParams[k] = params[k];
    }
  });
  return newParams;
};

export const getCommentsBranch = async (
  params: Partial<ICommentBranchParamsDTO>,
): Promise<ICommentBranch | null> => {
  const res = await get<ICommentDTO[], Partial<ICommentBranchParamsDTO>>(
    '/ajax/comments/comments_branch_get.php',
    clearNullAndUndefined(params),
  ).then(handleApiError);

  return res && res.id ? mapCommentBranchToFront(res) : null;
};

export const getComments = async (id_comments_branch: number): Promise<IComment[]> => {
  const res = await get<ICommentDTO[], { id_comments_branch: number }>(
    '/ajax/comments/comments_list.php',
    { id_comments_branch },
  ).then(handleApiError);

  return res.map(mapCommentToFront);
};

export const pinComment = async (id_comment: number, is_pinned: boolean): Promise<boolean> => {
  const res = await post<{ success?: boolean }, { id_comment: number; is_pinned: boolean }>(
    '/ajax/comments/comments_pin.php',
    { id_comment, is_pinned },
  ).then(handleApiError);

  return !!res.success;
};

export const addComment = async (params: ICommentAddDTO): Promise<number> => {
  const res = await post<{ id: string }, ICommentAddDTO>(
    '/ajax/comments/comments_add.php',
    params,
  ).then(handleApiError);

  return +res.id;
};

export const addCommentsBranch = async (
  params: Partial<ICommentBranchParamsDTO>,
): Promise<number> => {
  const res = await post<{ id: string }, Partial<ICommentBranchParamsDTO>>(
    '/ajax/comments/comments_branch_add.php',
    clearNullAndUndefined(params),
  ).then(handleApiError);

  return +res.id;
};
